import{_ as t,o as r,c as a,l as o,t as n,N as s}from"./chunks/framework.Gjrf2Eoj.js";const k=JSON.parse('{"title":"mkdir | x-cmd man (man1) | make directories","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | mkdir - make directories","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"mkdir | x-cmd man (man1) | make directories"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | mkdir - make directories"}]]},"headers":[],"params":{"isMan":true,"man":"mkdir","category":"man1","desc":"make directories"},"relativePath":"man1/mkdir.md","filePath":"man1/mkdir.md"}'),i={name:"man1/mkdir.md"},d={class:"visually-hidden"},l=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>mkdir - make directories</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>mkdir</strong> [<em>OPTION</em>]... <em>DIRECTORY</em>...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Create the DIRECTORY(ies), if they do not already exist.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-m</strong>, <strong>--mode</strong>=<em>MODE</em></dt><dd>set file mode (as in chmod), not a=rwx - umask</dd><dt><strong>-p</strong>, <strong>--parents</strong></dt><dd>no error if existing, make parent directories as needed, with their file modes unaffected by any <strong>-m</strong> option.</dd><dt><strong>-v</strong>, <strong>--verbose</strong></dt><dd>print a message for each created directory</dd><dt><strong>-Z</strong></dt><dd>set SELinux security context of each created directory to the default type</dd><dt><strong>--context</strong>[=<em>CTX</em>]</dt><dd>like <strong>-Z</strong>, or if CTX is specified then set the SELinux or SMACK security context to CTX</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>mkdir</strong>(2)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/mkdir%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/mkdir\\</a>&gt; <br> or available locally via: info &#39;(coreutils) mkdir invocation&#39;</p>',17);function m(e,c,h,g,p,u){return r(),a("div",null,[o("h1",d,n(e.$params.man),1),l])}const b=t(i,[["render",m]]);export{k as __pageData,b as default};
